import torch
import torch.nn as nn
import torch.nn.functional as F
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p42_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>
#include <vector>

torch::Tensor grubidir_hidden_only(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> flat_weights,
    bool has_bias,
    bool batch_first,
    int64_t num_layers,
    int64_t hidden_size
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("grubidir_hidden_only", &grubidir_hidden_only,
          "Bidirectional GRU hidden-only forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <vector>

// GRU gate pointwise kernel:
// Computes z, r, n gates and updates h in-place.
// gate_ih: (batch, 3*H) - input projections (already added bias_ih if present)
// gate_hh: (batch, 3*H) - hidden projections (already added bias_hh if present)
// h:       (batch, H)   - current hidden state, updated in-place
// H = hidden_size
__global__ void gru_cell_kernel(
    const float* __restrict__ gate_ih,
    const float* __restrict__ gate_hh,
    float* __restrict__ h,
    int batch,
    int H
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * H) return;
    int b = idx / H;
    int hh = idx % H;

    // PyTorch GRU gate order: reset(r), update(z), new(n)
    float r_ih = gate_ih[b * 3*H + hh];
    float z_ih = gate_ih[b * 3*H + H + hh];
    float n_ih = gate_ih[b * 3*H + 2*H + hh];

    float r_hh = gate_hh[b * 3*H + hh];
    float z_hh = gate_hh[b * 3*H + H + hh];
    float n_hh = gate_hh[b * 3*H + 2*H + hh];

    float r = 1.0f / (1.0f + expf(-(r_ih + r_hh)));
    float z = 1.0f / (1.0f + expf(-(z_ih + z_hh)));
    float n = tanhf(n_ih + r * n_hh);

    float h_cur = h[b * H + hh];
    h[b * H + hh] = (1.0f - z) * n + z * h_cur;
}

// Add bias vector to matrix rows: out[b, :] += bias[:]
__global__ void add_bias_kernel(
    float* __restrict__ out,
    const float* __restrict__ bias,
    int batch,
    int cols
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * cols) return;
    int col = idx % cols;
    out[idx] += bias[col];
}

static cublasHandle_t g_cublas_handle = nullptr;

static void ensure_cublas() {
    if (g_cublas_handle == nullptr) {
        cublasCreate(&g_cublas_handle);
    }
}

// sgemm helper: C = alpha * A * B^T + beta * C
// A: (M, K), B: (N, K) -> C: (M, N)
static void gemm_nt(
    float alpha, const float* A, int M, int K,
    const float* B, int N,
    float beta, float* C
) {
    // cublas is column-major; we want C = A * B^T
    // In column-major: C^T = B * A^T
    // cublasS gemm(handle, CUBLAS_OP_T, CUBLAS_OP_N, N, M, K, &alpha, B, K, A, K, &beta, C, N)
    cublasSgemm(g_cublas_handle,
        CUBLAS_OP_T, CUBLAS_OP_N,
        N, M, K,
        &alpha,
        B, K,
        A, K,
        &beta,
        C, N);
}

torch::Tensor grubidir_hidden_only(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> flat_weights,
    bool has_bias,
    bool batch_first,
    int64_t num_layers,
    int64_t hidden_size
) {
    ensure_cublas();

    // Validate and prepare inputs
    TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32, "x must be CUDA float32");
    TORCH_CHECK(h0.is_cuda() && h0.dtype() == torch::kFloat32, "h0 must be CUDA float32");

    x = x.contiguous();
    h0 = h0.contiguous();

    // x shape: (seq_len, batch, input_size) if batch_first=False
    int64_t seq_len, batch, input_size_val;
    if (batch_first) {
        batch = x.size(0);
        seq_len = x.size(1);
        input_size_val = x.size(2);
        x = x.permute({1, 0, 2}).contiguous();
    } else {
        seq_len = x.size(0);
        batch = x.size(1);
        input_size_val = x.size(2);
    }

    int64_t H = hidden_size;
    int64_t num_directions = 2; // bidirectional
    int weights_per_layer = has_bias ? 4 : 2;

    // h_n output: (num_layers * num_directions, batch, H)
    auto h_n = torch::empty({num_layers * num_directions, batch, H},
                             x.options());

    // Copy initial hidden states into h_n (we'll update in-place)
    h_n.copy_(h0);

    // Allocate gate buffers
    auto gate_ih = torch::empty({batch, 3 * H}, x.options());
    auto gate_hh = torch::empty({batch, 3 * H}, x.options());

    // For stacked layers: layer input is concatenated fwd+bwd hidden from previous layer
    // We need a scratch buffer for layer input (for layers > 0)
    // layer 0 input: x (seq_len, batch, input_size)
    // layer k>0 input: (seq_len, batch, 2*H)

    // Pre-allocate layer input buffers
    auto layer_input_0 = x; // (seq_len, batch, input_size)
    auto layer_input_k = torch::empty({seq_len, batch, 2 * H}, x.options());

    for (int64_t layer = 0; layer < num_layers; layer++) {
        // Pick current layer input
        torch::Tensor cur_input;
        int64_t cur_input_size;
        if (layer == 0) {
            cur_input = layer_input_0;
            cur_input_size = input_size_val;
        } else {
            cur_input = layer_input_k;
            cur_input_size = 2 * H;
        }

        // For next layer, we need per-timestep outputs of this layer
        // We build layer_input_k in-place during the timestep loops
        // We need fwd outputs and bwd outputs to interleave
        torch::Tensor fwd_out, bwd_out;
        if (layer < num_layers - 1) {
            fwd_out = torch::empty({seq_len, batch, H}, x.options());
            bwd_out = torch::empty({seq_len, batch, H}, x.options());
        }

        for (int64_t dir = 0; dir < num_directions; dir++) {
            int64_t layer_dir_idx = layer * num_directions + dir;
            int64_t w_base = layer_dir_idx * weights_per_layer;

            // Weight matrices
            // weight_ih: (3*H, input_size), weight_hh: (3*H, H)
            auto w_ih = flat_weights[w_base + 0].contiguous();     // (3H, in)
            auto w_hh = flat_weights[w_base + 1].contiguous();     // (3H, H)

            const float* b_ih_ptr = nullptr;
            const float* b_hh_ptr = nullptr;
            torch::Tensor b_ih_t, b_hh_t;
            if (has_bias) {
                b_ih_t = flat_weights[w_base + 2].contiguous();    // (3H,)
                b_hh_t = flat_weights[w_base + 3].contiguous();    // (3H,)
                b_ih_ptr = b_ih_t.data_ptr<float>();
                b_hh_ptr = b_hh_t.data_ptr<float>();
            }

            // Get hidden state slice for this layer/direction
            // h_n[layer_dir_idx]: (batch, H)
            float* h_ptr = h_n.data_ptr<float>() + layer_dir_idx * batch * H;

            const float* wih_ptr = w_ih.data_ptr<float>();
            const float* whh_ptr = w_hh.data_ptr<float>();
            float* gih_ptr = gate_ih.data_ptr<float>();
            float* ghh_ptr = gate_hh.data_ptr<float>();

            int threads = 256;
            int blocks_bias = (batch * 3 * H + threads - 1) / threads;
            int blocks_cell = (batch * H + threads - 1) / threads;

            // Iterate timesteps
            int64_t t_start = (dir == 0) ? 0 : seq_len - 1;
            int64_t t_end   = (dir == 0) ? seq_len : -1;
            int64_t t_step  = (dir == 0) ? 1 : -1;

            for (int64_t t = t_start; t != t_end; t += t_step) {
                // x_t: (batch, cur_input_size)
                const float* x_t = cur_input.data_ptr<float>() + t * batch * cur_input_size;

                // gate_ih = x_t @ w_ih^T  => (batch, 3H)
                float one = 1.0f, zero = 0.0f;
                cublasSgemm(g_cublas_handle,
                    CUBLAS_OP_T, CUBLAS_OP_N,
                    3*H, batch, cur_input_size,
                    &one,
                    wih_ptr, cur_input_size,
                    x_t, cur_input_size,
                    &zero,
                    gih_ptr, 3*H);

                // gate_hh = h @ w_hh^T  => (batch, 3H)
                cublasSgemm(g_cublas_handle,
                    CUBLAS_OP_T, CUBLAS_OP_N,
                    3*H, batch, H,
                    &one,
                    whh_ptr, H,
                    h_ptr, H,
                    &zero,
                    ghh_ptr, 3*H);

                // Add biases
                if (has_bias) {
                    add_bias_kernel<<<blocks_bias, threads>>>(
                        gih_ptr, b_ih_ptr, batch, 3*H);
                    add_bias_kernel<<<blocks_bias, threads>>>(
                        ghh_ptr, b_hh_ptr, batch, 3*H);
                }

                // GRU cell update
                gru_cell_kernel<<<blocks_cell, threads>>>(
                    gih_ptr, ghh_ptr, h_ptr, batch, H);

                // Save output for next layer if needed
                if (layer < num_layers - 1) {
                    if (dir == 0) {
                        cudaMemcpyAsync(
                            fwd_out.data_ptr<float>() + t * batch * H,
                            h_ptr,
                            batch * H * sizeof(float),
                            cudaMemcpyDeviceToDevice);
                    } else {
                        cudaMemcpyAsync(
                            bwd_out.data_ptr<float>() + t * batch * H,
                            h_ptr,
                            batch * H * sizeof(float),
                            cudaMemcpyDeviceToDevice);
                    }
                }
            }
        } // end dir loop

        // Build layer_input_k for next layer: interleave fwd and bwd outputs
        // layer_input_k[t, b, :] = cat(fwd_out[t,b,:], bwd_out[t,b,:])
        if (layer < num_layers - 1) {
            // fwd_out: (seq_len, batch, H), bwd_out: (seq_len, batch, H)
            // -> layer_input_k: (seq_len, batch, 2H)
            auto fwd_r = fwd_out.view({seq_len * batch, H});
            auto bwd_r = bwd_out.view({seq_len * batch, H});
            auto cat = torch::cat({fwd_r, bwd_r}, 1); // (seq_len*batch, 2H)
            layer_input_k = cat.view({seq_len, batch, 2 * H}).contiguous();
        }
    } // end layer loop

    return h_n;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                :param input_size: The number of expected features in the input x
                :param hidden_size: The number of features in the hidden state h
                :param num_layers: Number of recurrent layers (default: 1)
                :param bias: If False, then the layer does not use bias weights b_ih and b_hh (default: True)
                :param batch_first: If True, then the input and output tensors are provided as (batch, seq, feature) (default: False)
                """
        self.gru = nn.GRU(input_size, hidden_size, num_layers, bias, batch_first, dropout=0, bidirectional=True)
        # <<<END_IMPROVE>>>

    def forward(self, x,h0):
