                    h0.contiguous(),
                    flat_w,
                    self.gru.bias,
                    self.gru.batch_first,
                    self.gru.num_layers,
                    self.gru.hidden_size,
                )
            else:
                output, h_n = self.gru(x, h0)
        except Exception:
            output, h_n = self.gru(x, h0)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        return h_n
