# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <vector>

// GRU gate pointwise kernel:
// Computes z, r, n gates and updates h in-place.
// gate_ih: (batch, 3*H) - input projections (already added bias_ih if present)
// gate_hh: (batch, 3*H) - hidden projections (already added bias_hh if present)
// h:       (batch, H)   - current hidden state, updated in-place
// H = hidden_size
__global__ void gru_cell_kernel(
    const float* __restrict__ gate_ih,
    const float* __restrict__ gate_hh,
    float* __restrict__ h,
    int batch,
    int H
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * H) return;
    int b = idx / H;
    int hh = idx % H;

    // PyTorch GRU gate order: reset(r), update(z), new(n)
    float r_ih = gate_ih[b * 3*H + hh];
    float z_ih = gate_ih[b * 3*H + H + hh];
    float n_ih = gate_ih[b * 3*H + 2*H + hh];

    float r_hh = gate_hh[b * 3*H + hh];
    float z_hh = gate_hh[b * 3*H + H + hh];
    float n_hh = gate_hh[b * 3*H + 2*H + hh];

    float r = 1.0f / (1.0f + expf(-(r_ih + r_hh)));
    float z = 1.0f / (1.0f + expf(-(z_ih + z_hh)));
    float n = tanhf(n_ih + r * n_hh);

    float h_cur = h[b * H + hh];
    h[b * H + hh] = (1.0f - z) * n + z * h_cur;
}

// Add bias vector to matrix rows: out[b, :] += bias[:]
__global__ void add_bias_kernel(
    float* __restrict__ out,
    const float* __restrict__ bias,
    int batch,
    int cols
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * cols) return;
    int col = idx % cols;
    out[idx] += bias[col];
}

static cublasHandle_t g_cublas_handle = nullptr;

static void ensure_cublas() {
    if (g_cublas_handle == nullptr) {
        cublasCreate(&g_cublas_handle);
    }
}

// sgemm helper: C = alpha * A * B^T + beta * C
// A: (M, K), B: (N, K) -> C: (M, N)
static void gemm_nt(
    float alpha, const float* A, int M, int K,
    const float* B, int N,
    float beta, float* C
) {
    // cublas is column-major; we want C = A * B^T
    // In column-major: C^T = B * A^T
    // cublasS gemm(handle, CUBLAS_OP_T, CUBLAS_OP_N, N, M, K, &alpha, B, K, A, K, &beta, C, N)
    cublasSgemm(g_cublas_handle,
        CUBLAS_OP_T, CUBLAS_OP_N,
        N, M, K,
        &alpha,
        B, K,
        A, K,
        &beta,
        C, N);
}

torch::Tensor grubidir_hidden_only(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> flat_weights,
    bool has_bias,
    bool batch_first,
    int64_t num_layers,
    int64_t hidden_size
) {
    ensure_cublas();

    // Validate and prepare inputs
    TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32, "x must be CUDA float32");
    TORCH_CHECK(h0.is_cuda() && h0.dtype() == torch::kFloat32, "h0 must be CUDA float32");

    x = x.contiguous();
    h0 = h0.contiguous();

    // x shape: (seq_len, batch, input_size) if batch_first=False
    int64_t seq_len, batch, input_size_val;
    if (batch_first) {
        batch = x.size(0);
        seq_len = x.size(1);
        input_size_val = x.size(2);
        x = x.permute({1, 0, 2}).contiguous();
    } else {
        seq_len = x.size(0);
        batch = x.size(1);
        input_size_val = x.size(2);
    }

    int64_t H = hidden_size;
    int64_t num_directions = 2; // bidirectional
    int weights_per_layer = has_bias ? 4 : 2;

    // h_n output: (num_layers * num_directions, batch, H)
    auto h_n = torch::empty({num_layers * num_directions, batch, H},
                             x.options());

    // Copy initial hidden states into h_n (we'll update in-place)
    h_n.copy_(h0);

    // Allocate gate buffers
    auto gate_ih = torch::empty({batch, 3 * H}, x.options());
    auto gate_hh = torch::empty({batch, 3 * H}, x.options());

    // For stacked layers: layer input is concatenated fwd+bwd hidden from previous layer
    // We need a scratch buffer for layer input (for layers > 0)
    // layer 0 input: x (seq_len, batch, input_size)
    // layer k>0 input: (seq_len, batch, 2*H)

    // Pre-allocate layer input buffers
    auto layer_input_0 = x; // (seq_len, batch, input_size)
    auto layer_input_k = torch::empty({seq_len, batch, 2 * H}, x.options());

    for (int64_t layer = 0; layer < num_layers; layer++) {
        // Pick current layer input
        torch::Tensor cur_input;
        int64_t cur_input_size;
        if (layer == 0) {
            cur_input = layer_input_0;
            cur_input_size = input_size_val;
        } else {
            cur_input = layer_input_k;
            cur_input_size = 2 * H;
        }

        // For next layer, we need per-timestep outputs of this layer
        // We build layer_input_k in-place during the timestep loops
        // We need fwd outputs and bwd outputs to interleave
        torch::Tensor fwd_out, bwd_out;
        if (layer < num_layers - 1) {
            fwd_out = torch::empty({seq_len, batch, H}, x.options());
            bwd_out = torch::empty({seq_len, batch, H}, x.options());
        }

        for (int64_t dir = 0; dir < num_directions; dir++) {
            int64_t layer_dir_idx = layer * num_directions + dir;
