// Fused recurrent kernel: computes W_hh @ h_prev inline (no separate cuBLAS call)
// and applies GRU gating in one pass. One thread per (batch, hidden) element.
// gate_ih_t: precomputed input gates for this timestep, shape [batch, 3H]
// w_hh: [3H, H] row-major (PyTorch stores as [3H, H])
// h: [batch, H] in-out
__global__ void gru_fused_recurrent_kernel(
    const float* __restrict__ gate_ih_t,
    const float* __restrict__ w_hh,
    const float* __restrict__ b_ih,
    const float* __restrict__ b_hh,
    float* __restrict__ h,
    int batch,
    int H,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * H) return;
    int b = idx / H;
    int hh = idx % H;

    // Read precomputed input-side gates
    float r_ih = gate_ih_t[b * 3*H + hh];
    float z_ih = gate_ih_t[b * 3*H + H + hh];
    float n_ih = gate_ih_t[b * 3*H + 2*H + hh];

    // Compute recurrent projection W_hh @ h_prev for this (batch, hidden) element
    // w_hh layout: [3H, H], so row i is w_hh[i*H .. i*H+H-1]
    // We need dot(w_hh[gate_row, :], h[b, :]) for gate_row in {hh, H+hh, 2H+hh}
    const float* h_b = h + b * H;
    float r_hh = 0.0f, z_hh = 0.0f, n_hh = 0.0f;
    const float* w_r = w_hh + hh * H;
    const float* w_z = w_hh + (H + hh) * H;
    const float* w_n = w_hh + (2*H + hh) * H;
    for (int k = 0; k < H; k++) {
        float hk = h_b[k];
        r_hh += w_r[k] * hk;
        z_hh += w_z[k] * hk;
        n_hh += w_n[k] * hk;
