    if (has_bias) {
        r_ih += b_ih[hh];       z_ih += b_ih[H + hh];     n_ih += b_ih[2*H + hh];
        r_hh += b_hh[hh];       z_hh += b_hh[H + hh];     n_hh += b_hh[2*H + hh];
