    float r = 1.0f / (1.0f + expf(-(r_ih + r_hh)));
    float z = 1.0f / (1.0f + expf(-(z_ih + z_hh)));
    float n = tanhf(n_ih + r * n_hh);

    float h_cur = h[b * H + hh];
    h[b * H + hh] = (1.0f - z) * n + z * h_cur;
